import numpy as np
L=np.log(eps); one=np.ones(300)
Fs={'1':one,'L':L,'1/e':1/eps,'e':eps,'eL':eps*L,'L2':L*L,'1/e2':1/eps**2,'T/e':None}
cols=[];names=[]
for fk in ['1','L','1/e','e','eL','L2','1/e2']:
    fv=Fs[fk]
    for j in range(5):
        cols.append(fv*T**j);names.append(f'{fk}*T{j}')
A=np.column_stack(cols)
c=np.linalg.lstsq(A,sigma,rcond=None)[0]
r=sigma-A@c
print(np.mean(r**2)/np.var(sigma))
print(np.linalg.matrix_rank(A))
for n_,v in zip(names,c):
    if abs(v)>1e-3: print(n_, round(v,4))
